from collections import defaultdict

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_right_permutations(n, arr):
    mod = 10**9 + 7
    dp = defaultdict(int)
    dp[-1, 0] = 1  # Base case: empty product

    for i in range(n):
        prev_sum = 0  # Reset for current entry into dp array
        for j in range(i):
            val = arr[i] * arr[j]
            if val < 1_000_000_000 and is_prime(val):
                val -= 1_000_000_000  # Subtract a specific factor (difference is constant)
                val = val % mod
            dp[j, val] += dp[j, prev_sum]  # Update dp for j, val
        prev_sum = val

    return sum(dp[dp.size() - 1, i] for i in range(1000_000_000, (-1 if arr[-1]**0.5 % 1 != 0 else -10**9))) % mod

