from collections import defaultdict

def sieve_of_eratosthenes(n):
    prime = [0] * (n + 1)
    prime[0] = 1
    prime[1] = 1
    p = 2
    while p * p <= n:
        if not prime[p]:
            for i in range(p * p, n + 1, p):
                prime[i] = 1
        p += 1
    return [i for i in range(n + 1) if not prime[i]]

def palindromic_paths(n, edges, labels):
    graph = defaultdict(lambda: set())
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    possible_palindromes = [0] * n
    visited = [False] * n
    for root in range(n):
        if visited[root]:
            continue
        visited[root] = True
        stack = [root]
        while stack:
            current = stack.pop()
            prefix = labels[current]
            possible_palindromes[current] += count_possible_palindromes(len(prefix), prefix)
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    stack.append(neighbor)
                    visited[neighbor] = True
    return possible_palindromes

def count_possible_palindromes(n, prefix):
    i = (n - 1) // 2
    total = 1
    while i >= 0:
        if i < n - i - 1 and prefix[i] != prefix[n - i - 1]:
            total *= 2
            prefix = prefix[1:] + prefix[:1]
        i -= 1
    k = (n - 1) // 2
    for index in range(k):
        total *= (2 ** index)
        j = index
        while j < k - index - 1 and (prefix[index] == prefix[k - index - 1]):
            j += 1
        prefix_data = list(reversed(prefix))  # reverse by indices separately.
        prefix_data.insert(0, prefix[-1])
        prefix = "".join(prefix_data)
    return total
