    pass_positions = set()
    for r in range(n):
        for c in range(m):
            if commands[r][c] == '.':
                pass_positions.add((r, c))

    if not pass_positions:
        return -1

    visited = set()
    search_queue = deque()
    search_queue.extend(pass_positions)

    while search_queue:
        r, c = search_queue.popleft()
        if (r, c) not in visited:
            visited.add((r, c))
            if (r, c) != ('-1', '-1'):
                height = 'YN'[r + 50]  # Assuming ASCII values for simplicity
                width = 'W'[c + 50]
                if height and width and height + width == 'YY':
                    return commands[r][c]
                elif not height and not width:
                    return 0

        neighbors = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for diff_r, diff_c in neighbors:
            new_r, new_c = r + diff_r, c + diff_c
            if 0 <= new_r < n and 0 <= new_c < m and commands[new_r][new_c] not in ['#$', 'E']:
