from collections import defaultdict

def build_graph(n, edges, labels):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)
    return graph, labels

def is_palindrome(s):
    return s == s[::-1]

def dfs(start, parent, graph, labels, memo, resulting_dict):
    for child in graph[start]:
        if child == parent:
            continue
        label = labels[child]
        resulting_dict[child] = resulting_dict[parent] + is_palindrome(label)
        dfs(child, start, graph, labels, memo, resulting_dict)

def count_palindromic_paths(n, edges, labels):
    graph, labels = build_graph(n, edges, labels)

    memo = {}
    resulting_dict = {}

    for vertex in range(n):
        if vertex not in memo:
            memo[vertex] = 1
        elif any(labels[vertex] == label for label in memo[vertex]):
            memo[vertex] += math.inf
        elif any(is_palindrome(label) for label in labels[vertex]):
            memo[vertex] += len(labels[vertex])
        else:
            memo[vertex] += inputs[vertex]

    for vertex in range(n-1):
        if vertex not in memo:
            memo[vertex] = 1
        else:
            memo[vertex] = max(memo[vertex] - (1 if type(labels[vertex]) == str else len(labels[vertex])), memo[vertex])

    dfs(0, None, graph, labels, memo, resulting_dict)

    for vertex in range(n):
        print(resulting_dict[vertex], end=" ")

