import sys

def inside_poly(x, y, xs, ys):
    """Count interior points of polygon with (x0, y0) as left point."""
    inpt = 0
    j = len(xs) - 1
    for i in range(len(xs)):
        if (ys[j] > y >= ys[i]) or (ys[j] < y <= ys[i]):
            if x >= xs[j] - (xs[j] - xs[i]) * (ys[j] - y) / (ys[j] - ys[i]):
                inpt += 1
        j = i
    return inpt

def area(max_x, max_y, poly):
    """Calculate area of possibly int triangles in a polygon"""
    a = b = 0
    xs = []
    ys = []
    for i in range(len(poly)):
        xs.append(poly[i][0])
        ys.append(poly[i][1])
    a += max_x - xs[-1]
    b += max_y - ys[-1]
    for i in range(1, len(xs)):
        a = a + (xs[i - 1] + xs[i]) * (ys[i - 1] - ys[i])
        b = b + (ys[i - 1] + ys[i]) * (xs[i - 1] - xs[i])
    a = a // 2.0
    b = b // 2.0
    return sqrt(a * b)

