import sys

def find_shortest_move_sequence(n, m, layout, commands):
    def is_valid_index(r, c):
        return 0 <= r < n and 0 <= c < m and layout[r][c] != "#"

    moves = {"L": (-1, 0), "R": (1, 0), "U": (0, -1), "D": (0, 1)}
    queue = deque([(0, 0, 0)])
    seen = set([(0, 0, 0)])
    grid = []
    for _ in range(n):
        grid.append(layout[1:])
        grid[-1].insert(0, "#")
    grid[-1].appendleft("#")

    path_distances = set()
    queue = deque([(0, (0, (len(layout[1:]) // 2, -1)))])

    while queue:
        distance, reached = queue.popleft()
        if distance >= commands:
            width = len(reached[1])
            for direc in "RDLU":
                y, x = reached[1][width - 1]
                for i in range(4):
                    nextx, nexty = x + moves[direc][0] * i, y + moves[direc][1] * i
                    nextx, nexty = max(nextx, 0), max(nexty, 0)
                    nextx, nexty = min(nextx, m - 1), min(nexty, n - 1)
                    next = grid[nexty][nextx]
                    grid[nexty][nextx] = "#"
                    if next == ".":
                        path_distances.add((nexty, nextx, distance - commands - 1))
                    elif next == "#":
                        grid[nexty][nextx] = "."
                    elif next == "E":
                        return commands, [d for d, (y, x) in zip(commands, reached[1]) if d == direc][0]

                    # Move manifolds by unparalleled steps
                    if is_valid_index(y, x) and is_valid_index(nexty, nextx):
                        if (nexty, nextx, distance - commands - 1) in seen:
                            neighbors = 1
                            for other in "RDLU":
                                ny, nx = nexty + moves[other][1], nextx + moves[other][0]
                                if is_valid_index(ny, nx) and grid[ny][nx] != "#":
                                    neighbors += 4
                                another_neighbor = (ny, nx, distance - commands - 1)
                                if another_neighbor in seen:
                                    neighbors -= 1
                            queue.append((distance + 1, reached + (direc, direc not in ("D", "U") and i % 2), neighbors))
                        else:
                            queue.append((distance + 1, reached + (direc, None), neighbors))

        if len(path_distances) > 500:
            path_distances.clear()

    return -1

