def find_robot_exit(basement, commands):
    n, m = len(basement), len(basement[0])
    visited = [[False] * m for _ in range(n)]

    # Initialize based on the first command
    new_position = find_initial_position(basement, commands)
    if not new_position:
        return "-1"

    direction = '='

    for command in commands:
        if command == "L":
            direction = "<"
        elif command == "R":
            direction = ">"
        elif command == "U":
            direction = "^"
        elif command == "D":
            direction = "v"
        if check_position(basement, new_position[0], new_position[1], direction):
            new_position = change_position(basement, new_position[0], new_position[1], direction)

    if visited[new_position[0]][new_position[1]]:
        return "-1"

    while not is_exit(basement, new_position[0], new_position[1]):
        if command_count(basement, 'L', new_position[0], new_position[1]) > command_count(basement, 'R', new_position[0], new_position[1]):
            new_position = flip_position(new_position, ">")
        elif command_count(basement, "R", new_position[0], new_position[1]) > command_count(basement, "L", new_position[0], new_position[1]):
            new_position = flip_position(new_position, "<")
        elif command_count(basement, "U", new_position[0], new_position[1]) > command_count(basement, "D", new_position[0], new_position[1]):
            new_position = flip_position(new_position, "v")
        elif command_count(basement, "D", new_position[0], new_position[1]) > command_count(basement, "U", new_position[0], new_position[1]):
            new_position = flip_position(new_position, "^")
        visited[new_position[0]][new_position[1]] = True

    return command_count(basement, 'R', new_position[0], new_position[1]) + command_count(basement, 'L', new_position[0], new_position[1])

def command_count(basement, direction, x, y):
    count = 0
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(basement) and 0 <= ny < len(basement[0]) and basement[nx][ny] == '.' and command_count(basement, direction, nx, ny) < 4:
            count += 1
    return count

def find_initial_position(basement, commands):
    x, y = commands.index('E')+1, 0
    while y < len(basement[0]) and not boolean(basement, x, y):
        y += 1
    return x, y

def is_exit(basement, x, y):
    return boolean(basement, x, y) and basement[x][y] == "E"

def boolean(basement, x, y):
    return 0 <= x < len(basement) and 0 <= y < len(basement[0]) and basement[x][y] == "."

def flip_position(position, direction):
    x, y = position
    if direction == ">":
        return (x, y-1)
    elif direction == "<":
        return (x, y+1)
    elif direction == "^":
        return (x-1, y)
    elif direction == "v":
        return (x+1, y)

def change_position(basement, x, y, direction):
    nx, ny = x + dx, y + dy
    return nx, ny

def check_position(basement, x, y, direction):
    nx, ny = x + dx, y + dy
    return (0 <= nx < len(basement) and 0 <= ny < len(basement[0]) and (basement[nx][ny] == "#" or nx == x and ny == y))

