def convert2Coords(row, col):
    # Convert the input row and column to coordinates with row 1 being y and col 1 being x
    return (row - 1, col)

def find_king(row, col):
    # Find the position of the king based on initial coordinates
    return convert2Coords(row, col)

def find_rooks(pos, king_pos):
    # Given the position of the king, find positions for the rooks
    rooks = []
    x, y = king_pos
    maximum_edge = max(abs(row - x) for row in pos)
    for r in pos:
        if r == x: continue
        if maximum_edge == 1 and r > x and r + 1 == x:
            rooks.append(find_king(r, coord) for coord in [(y, r), (r + 1, y)]) # Up or Diagonal
        elif maximum_edge == 0 and r > x:
            rooks.append(find_king(r, coord)) for coord in [(y - 1, r), (r, y - 1)])  # Up-left or Down-right
        elif maximum_edge == 0 and r < x:
            rooks.append(find_king(r, coord)) for coord in [(y + 1, r), (r, y + 1)])  # Down-left or Up-right
        elif r < x:
            rooks.append(find_king(r, coord)) for coord in [(y, r + 1), (r + 1, y)])  # Down or Diagonal
        elif r > x:
            rooks.append(find_king(r, coord)) for coord in [(y, r - 1), (r - 1, y)])  # Up or Diagonal
    return rooks

