from collections import defaultdict

def find_non_duplicate_element(nums):
    num_dict = {}
    for num in nums:
        if num in num_dict:
            num_dict[num] += 1
        else:
            num_dict[num] = 0
    for key, value in num_dict.items():
        if value != 0:
            return key

def find_mapping(N, bus_routes, train_routes):
    city_list = list(range(1, N + 1))
    already_visited_buses = set()
    already_visited_trains = set()
    current_sequence = []
    remaining_buses = set()
    remaining_trains = set(range(N + 1, 2 * N + 1))

    def dfs(buyer, to_buyer, demand_source=None):
        if buyer == to_buyer:
            nonlocal current_sequence
            current_sequence.append(buyer)
            return
        if destination is None:
            if demand_source != None and len(destination) < 2:
                return remaining_trains - destination
        destination = demand_source if buyer == demand_source else destination - demand_source
        current_sequence.append(buyer)
        dfs(destination - buyer, to_buyer)
        destination = destination - buyer

    # Find a mapping for public transportation
    non_fire = find_non_duplicate_element(bus_routes)

    for bus_route, train_route in zip(sorted(bus_routes), sorted(train_routes)):
        if bus_route[0] == non_fire:
            original_bus = bus_route
        else:
            non_fire = find_non_duplicate_element([sorted(b) for b in bus_routes])
            best_new_bus = find_non_duplicate_element(train_routes)
            for bus_source in range(N):
                bus_sources = []
                for bus_destination in bus_routes[bus_source]:
                    if bus_destination == original_bus[0]:
                        bus_sources.append(bus_destination)
                if best_new_bus not in bus_sources:
                    continue
                else:
                    non_fire = find_non_duplicate_element([sorted(b) for b in bus_routes])
                    destination = set(sorted(bus_sources).union(train_routes))
                    dfs(0, non_fire, destination)
                    best_new_bus = bus_route

    # Form the mapping between the two numbering schemes
    j = 0
    for i in range(1, 2 * N + 1):
        if i in remaining_trains:
            city_list[j] = find_non_duplicate_element([sorted(b) for b in remaining_trains])
            j += 1
        elif i in remaining_buses:
            city_list[j] = non_fire
            j += 1
    return j == N

