def handle_bus_edges(edges):
    adj = nx.Graph()
    for u, v in edges:
        adj.add_edge(u, v)

    result = nx.k_compatible_set_cover(adj, bus_edges=True)
    mapping_no_pruned = {u: u for u in adj}
    mapping_bus = mapping_no_pruned
    for bus_edges in result:
        mapping_no_pruned = {u: v for u, v in bus_edges}
        for u, v in mapping_no_pruned.items():
            if mapping_bus[u] != v:
                mapping_no_pruned[v] = u
        mapping_bus = {u: v for u, v in mapping_no_pruned.items()}

    return "Yes" if len(mapping_no_pruned) == len(mapping_bus) else "No"

def check_solution(mapping, bus_edges, rail_edges):
    for u, v in bus_edges:
        assert mapping[u] != mapping[v]
    for u, v in rail_edges:
        assert mapping[u] == mapping[v]

def solve(n, bus_edges, rail_edges):
    bus_graph = nx.Graph()
    bus_graph.add_edges_from([(u, v) for u, v in bus_edges])
    rail_graph = nx.Graph()
    rail_graph.add_edges_from([(u, v) for u, v in rail_edges])

    mapping = {u: 2 * n + v for u, v in enumerate(list(range(n)))}
    bus_edges = [(u, v) for u, v in bus_edges]
    rail_edges = [(n + v - u, n + v - u) for u, v in enumerate(list(range(1, n)))] + [(2 * n, 2 * n)]

    for perm in permutations(list(range(1, n + 1)), len(mapping)):
        if handle_bus_edges(zip(bus_edges + rail_edges, list(perm))):
            check_solution(mapping, bus_edges, rail_edges)
            return mapping

