def subsequence_count(s, n):
    count = [0] * n
    for i in range(n):
        if i > 0:
            count[i] = count[i-1] + 1 if s[i] != s[i-1] else count[i-1]
    return count

def find_subsequence(s, n):
    s = s.lower()
    count1 = subsequence_count(s, n)
    count2 = subsequence_count(s[::-1], n)
    if count1 == [0] * n or count2 == [0] * n:
        return -1
    sub = abs(sum(count1) - sum(count2))
    if sub % 3 != 0 or sub > 2:
        return -1
    mid = sub // 3
    length = 0
    best = []
    for i in range(n):
        if count1[i] - count1[i-length] - 1 - mid < 0:
            length += 1
        else:
            best.append((i-length+1, i-length+1-mid))
            length = 0
    return s[s.index(best[0][0]):s.index(best[0][1])+1]

