def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def count_pairs(l, r):
    def gcd_pairs(lo, hi):
        count = 0
        for i in range(lo, hi + 1):
            for j in range(lo, hi + 1):
                if gcd(i, j) >= l:
                    count += 1
        return count

    # Divide the interval [l, r] into intervals of size (r - l + 1) // k
    k = r - l + 1 // (r - l + 1) & -r + 1
    return sum(count_pairs(lo, hi) for lo in range(l, r + 1, k)) + count_pairs(l, r + k - 1)

