import collections
import itertools
import math

def move_rook(r, x, y):
    rooks = set()
    directions = [(0, 1), (1, 0)]
    for dx, dy in directions:
        while x + dx >= 1 and x + dx <= 999 and y + dy >= 1 and y + dy <= 999:
            rooks.add((x + dx, y + dy))
            x += dx
            y += dy
            if (r, x, y) in rooks:
                break

    if (r, x, y) in rooks:
        return (1, x + dx - r, y + dy - r)
    else:
        return (r, x, y)

def check_check(r, x, y):
    directions = [(0, 1), (1, 0)]
    for dx, dy in directions:
        while x + dx >= 1 and x + dx <= 999 and y + dy >= 1 and y + dy <= 999:
            if (r, x + dx, y + dy) in rooks:
                return True
            x += dx
            y += dy
    return False

def simulate_game():
    rooks = set()
    rooks.add((1, 1))
    rooks.add((1, 2))
    kings_moves = collections.deque([1, 1, 1])  # x, y, possible moves
    moves_executed = 0

    while moves_executed < 2000:
        moves_executed += 1

        if kings_moves[0] == -1:
            kings_moves = [1, 1, 1]  # If the king is in check, start with 1
        x, y = kings_moves[1], kings_moves[2]
        if kings_moves[3]:  # If the king was checked here, adjust legal moves
            directions = [(0, 1), (1, 0)]
            valid_moves = set()
            for dx, dy in directions:
                while x + min(-dx, 1) + dx >= 1 and x + min(-dx, 1) + dx <= 999 and y + min(-dy, 1) + dy >= 1 and y + min(-dy, 1) + dy <= 999:
                    if (x + min(-dx, 1) + dx, y + min(-dy, 1) + dy) not in rooks:
                        valid_moves.add((x + min(-dx, 1) + dx, y + min(-dy, 1) + dy))
            if valid_moves:
                kings_moves[2] = (x - dx, y - dy)
                if (r := kings_moves[3], x + dx - r, y + dy - r) in rooks and check_check(r, x, y):
                    kings_moves[3] = 1  # Back to previous king movement
                else:
                    kings_moves[3] = min(valid_moves)  # Move to valid airspace after initial check

        x, y = kings_moves[1] + kings_moves[0] % 2, kings_moves[2] + kings_moves[0] // 2
        if kings_moves[3]:  # If the king was checked here, adjust legal moves
            directions = [(0, 1), (1, 0)]
            valid_moves = set()
            for dx, dy in directions:
                while x + min(-dx, 1) + dx >= 1 and x + min(-dx, 1) + dx <= 999 and y + min(-dy, 1) + dy >= 1 and y + min(-dy, 1) + dy <= 999:
                    if (x + min(-dx, 1) + dx, y + min(-dy, 1) + dy) not in rooks:
                        valid_moves.add((x + min(-dx, 1) + dx, y + min(-dy, 1) + dy))
            if valid_moves:
                kings_moves[2] = (x - dx, y - dy)
                if (r := kings_moves[3], x + dx - r, y + dy - r) in rooks and check_check(r, x, y):
                    kings_moves[3] = 1  # Back to previous king movement
                else:
                    kings_moves[2] = min(valid_moves)  # Move to valid airspace after initial check

        (r, x_new, y_new) = move_rook(r, x, y)
        if (r, x_new, y_new) in rooks:
            king_moves = kings_moves[:4]
            king_moves = kings_moves[0:2] + (int(math.log(king_moves[2].x - 1) / int(math.log(2))),)
            kings_moves = [999] + king_moves
            kings_moves[2] = x_new, y_new
