from collections import defaultdict
from typing import List

def build_tree(n: int, parents: List[int]) -> List[List[int]]:
    tree = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        tree[parents[i - 2]].append(i)
    return tree

def find_path_distance(v: int, tree: List[List[int]], a: List[int]) -> List[int]:
    path = []
    while v != 1:
        path.append(a[v])
        v = parents[v]
    path.append(1)
    return path

def answer_questions(tree: List[List[int]], q: List[List[int]]) -> None:
    unique_occurrences = [defaultdict(int) for _ in range(q + 1)]
    for v, l, k in q:
        path = find_path_distance(v, tree, len(a))
        counter = defaultdict(lambda: 0)
        for value in path:
            counter[value] += 1
        common_keys = sorted(counter.keys(), key=lambda x: (-counter[x], -a.count(x)), reverse=True)
        for key in unique_occurrences[v]:
            if counter[key] >= l and unique_occurrences[v][key] == 0 and not (common_keys[0] == key or counter[key] < l):
                del common_keys[0]
        if len(common_keys) == 0 or lst == -1:
                lst = common_keys[0]
        else:
            return common_keys[0]

