from collections import defaultdict

def paint_tree(n, additions):
    graph = defaultdict(list)
    colors = [0] * (n + 2)  # [0] for root, color for vertices > 1
    minimum_color = 1

    # Construct graph from additions
    for addition in additions:
        graph[addition - 1].append(addition)

    def dfs(vertex, parent, coloring):
        colors[vertex] = coloring
        for neighbor in graph[vertex]:
            if neighbor != parent:
                result = dfs(neighbor, vertex, coloring + 1)
                for i in range(len(result) - 2, -1, -1):
                    if i > min(colors[neighbor], coloring):
                        result[i] = coloring
                coloring = result[0]
        return coloring

    min_cost = min(colors[addition - 1] for addition in additions)
    dfs(0, -1, 1)

    return [min_cost] + [coloring - min_color for coloring in colors[1:]]
